/**
 * Loads modules contributed by Shale extensions (see `modules/registry.js`, generated by
 * `bun run browser:build`) and gives each one a runtime scoped to its own processor.
 * Modules never import core files; everything they need comes through the runtime.
 */
import {
  settings,
  registerDefaults,
  policyFor,
  moduleEnabled,
} from "../settings.js";
import { enqueueRecords, hasRecord, nextSequence } from "../outbox.js";
import { deliverOutbox } from "../delivery.js";
import { createJob, resumeJobs } from "../jobs.js";

const hostMatches = (hostname, host) =>
  hostname === host || hostname.endsWith(`.${host}`);

export function createHost(registry) {
  const modules = [];
  const byId = new Map();
  const host = {
    modules,
    get: (id) => byId.get(id),
    async enabled() {
      const config = await settings();
      return modules.filter((m) => moduleEnabled(config, m.id));
    },
    /** The enabled module that claims a URL's host, if any. */
    async claimant(url) {
      let hostname;
      try {
        hostname = new URL(url).hostname.toLowerCase();
      } catch {
        return undefined;
      }
      return (await host.enabled()).find((m) =>
        (m.definition.claims?.hosts || []).some((h) =>
          hostMatches(hostname, h.toLowerCase()),
        ),
      )?.id;
    },
    handlerFor(job) {
      return byId.get(job.module)?.definition.jobs?.[job.kind];
    },
    resumeJobs: () => resumeJobs(host.handlerFor),
  };
  for (const entry of registry) {
    const runtime = createRuntime(entry, host);
    const definition = entry.register(runtime);
    if (definition.id !== entry.id)
      throw new Error(
        `Chrome module ${entry.id} registered itself as ${definition.id}`,
      );
    if (!definition.protocol?.validate || !definition.protocol.batchType)
      throw new Error(`Chrome module ${entry.id} has no protocol`);
    registerDefaults(definition.defaults || {});
    const module = { id: entry.id, label: definition.label || entry.id, definition, runtime };
    modules.push(module);
    byId.set(entry.id, module);
  }
  return host;
}

function createRuntime(entry, host) {
  const id = entry.id;
  const route = () => {
    const { protocol } = host.get(id).definition;
    return {
      processor: id,
      batchType: protocol.batchType,
      protocolVersion: protocol.version,
      validate: protocol.validate,
    };
  };
  const key = (name) => `module:${id}:${name}`;
  const runtime = {
    id,
    settings,
    async enqueue(records) {
      return enqueueRecords(records, await settings(), route());
    },
    hasRecord,
    nextSequence,
    deliver: () => deliverOutbox(),
    /** Module-private persistent values in `chrome.storage.local`. */
    storage: {
      async get(name, fallback) {
        const saved = await chrome.storage.local.get(key(name));
        return saved[key(name)] ?? fallback;
      },
      async set(name, value) {
        await chrome.storage.local.set({ [key(name)]: value });
      },
    },
    async policy() {
      return policyFor(await settings(), id);
    },
    async enabled() {
      return moduleEnabled(await settings(), id);
    },
    /** True when another enabled module owns this URL's host. */
    async claimedByOther(url) {
      const owner = await host.claimant(url);
      return owner !== undefined && owner !== id;
    },
    /** Queue a job; it runs on the next `resume()`, module action, or wake. */
    createJob: (kind, fields) => createJob(id, kind, fields),
    resume() {
      return host.resumeJobs().then(deliverOutbox);
    },
    /** Run one of this module's injected scripts in a tab and return its result. */
    async inject(tabId, name, { documentId, args } = {}) {
      if (!entry.inject?.includes(name))
        throw new Error(`Chrome module ${id} has no injected script ${name}`);
      const target = documentId
        ? { tabId, documentIds: [documentId] }
        : { tabId };
      await chrome.scripting.executeScript({
        target,
        files: [`modules/${id}/inject/${name}.js`],
      });
      const [result] = await chrome.scripting.executeScript({
        target,
        func: (slot, input) => globalThis.__shaleInjected[slot](input),
        args: [`${id}/${name}`, args ?? null],
      });
      return result?.result;
    },
    /** Run a self-contained function in a tab, e.g. a same-origin fetch with the page's session. */
    async execInTab(tabId, func, args = []) {
      const [result] = await chrome.scripting.executeScript({
        target: { tabId },
        func,
        args,
      });
      return result?.result;
    },
    log: (...items) => console.warn(`Shale ${id}:`, ...items),
  };
  return runtime;
}
